glmgeneralizedResults = if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "glmgeneralizedResults",
    inherit = jmvcore::Group,
    active = list(
        waiting = function() private$.items[["waiting"]],
        specification = function() private$.items[["specification"]],
        explanation = function() private$.items[["explanation"]],
        plot = function() private$.items[["plot"]],
        plotExplanation = function() private$.items[["plotExplanation"]],
        coefficients = function() private$.items[["coefficients"]],
        irt = function() private$.items[["irt"]],
        probabilities = function() private$.items[["probabilities"]],
        comparisonplot = function() private$.items[["comparisonplot"]],
        comparisonPlotExplanation = function() private$.items[["comparisonPlotExplanation"]],
        comparison = function() private$.items[["comparison"]]),
    private = list(),
    public=list(
        initialize=function(options) {
            super$initialize(
                options=options,
                name="",
                title="Generalized Linear Model",
                refs=list(
                    "flexplot",
                    "graphicalAnalysis"))
            self$add(jmvcore::Html$new(
                options=options,
                name="waiting",
                title="",
                content="<p>Select an outcome and predictors, and specify at least one model term.</p>"))
            self$add(jmvcore::Html$new(
                options=options,
                name="specification",
                title="Model specification",
                visible=FALSE))
            self$add(jmvcore::Html$new(
                options=options,
                name="explanation",
                title="Interpretation",
                visible=FALSE))
            self$add(jmvcore::Image$new(
                options=options,
                name="plot",
                title="Model visualization",
                width=700,
                height=450,
                visible=FALSE,
                renderFun=".plot"))
            self$add(jmvcore::Html$new(
                options=options,
                name="plotExplanation",
                title="",
                visible=FALSE))
            self$add(jmvcore::Table$new(
                options=options,
                name="coefficients",
                title="Estimates",
                visible=FALSE,
                columns=list(
                    list(
                        `name`="term",
                        `title`="Term",
                        `type`="text"))))
            self$add(jmvcore::Table$new(
                options=options,
                name="irt",
                title="IRT estimates",
                visible=FALSE,
                columns=list(
                    list(
                        `name`="variable",
                        `title`="Predictor",
                        `type`="text"),
                    list(
                        `name`="instantaneous_slope",
                        `title`="Slope (p = .5)",
                        `type`="number"),
                    list(
                        `name`="intercept_threshold",
                        `title`="Threshold (p = .5)",
                        `type`="number"))))
            self$add(jmvcore::Table$new(
                options=options,
                name="probabilities",
                title="Marginal predicted probabilities",
                visible=FALSE,
                columns=list(
                    list(
                        `name`="Variable",
                        `title`="Variable",
                        `type`="text"),
                    list(
                        `name`="Level",
                        `title`="Level",
                        `type`="text"),
                    list(
                        `name`="Probability",
                        `title`="Probability",
                        `type`="number"))))
            self$add(jmvcore::Image$new(
                options=options,
                name="comparisonplot",
                title="Model comparison plot",
                width=700,
                height=450,
                visible=FALSE,
                renderFun=".comparisonplot"))
            self$add(jmvcore::Html$new(
                options=options,
                name="comparisonPlotExplanation",
                title="",
                visible=FALSE))
            self$add(jmvcore::Table$new(
                options=options,
                name="comparison",
                title="Model comparison statistics",
                visible=FALSE,
                columns=list(
                    list(
                        `name`="model",
                        `title`="Model",
                        `type`="text"),
                    list(
                        `name`="n",
                        `title`="N",
                        `type`="integer"),
                    list(
                        `name`="aic",
                        `title`="AIC",
                        `type`="number"),
                    list(
                        `name`="bic",
                        `title`="BIC",
                        `type`="number"),
                    list(
